def operation(n):
    if n == 0:
        # Should not happen with positive starting integers, but good practice.
        return 0
    d = n % 10  # Last digit
    n_prime = n // 10 # Remaining number
    return n_prime + 3 * d

def simulate(start_n, steps=5):
    results = {0: start_n}
    current_n = start_n
    for i in range(1, steps + 1):
        current_n = operation(current_n)
        results[i] = current_n
    return results

test_cases = [12, 34, 99, 100]
all_results = {}

for n in test_cases:
    all_results[n] = simulate(n)

print("--- Simulation Results ---")
for start_n, results in all_results.items():
    print(f"\nStarting N = {start_n}")
    # Print the steps: Step 0 (start), Step 1, ..., Step 5
    steps_output = []
    for step in range(6):
        if step in results:
            steps_output.append(str(results[step]))
    print(" -> ".join(steps_output))
